<div class="a-cols"><div><div class="panel"><?php foreach ($items as $i): ?><div class="mini-line"><div class="mini-img"><img src="<?= e(product_image($i['image'])) ?>" width="56" height="70" alt=""><span class="mini-qty"><?= (int) $i['qty'] ?></span></div><div><strong><?= e($i['name']) ?></strong><p class="muted small">Size <?= e($i['size']) ?></p></div><span><?= money($i['price'] * $i['qty']) ?></span></div><?php endforeach; ?>
<div class="row"><span>Subtotal</span><span><?= money($order['subtotal']) ?></span></div><div class="row"><span>Discount <?= e($order['coupon_code']) ?></span><span>- <?= money($order['discount']) ?></span></div><div class="row"><span>Shipping</span><span><?= money($order['shipping']) ?></span></div><div class="row"><span>COD fee</span><span><?= money($order['cod_fee']) ?></span></div><div class="row total"><span>Total</span><strong><?= money($order['total']) ?></strong></div>
<p class="muted small"><?= e(strtoupper($order['payment_method'])) ?> &middot; <?= e($order['payment_status']) ?> <?= e($order['payment_ref']) ?></p></div>
<div class="panel"><h3>Customer</h3><p><?= e($order['ship_name']) ?><br><?= e($order['email']) ?> &middot; <?= e($order['phone']) ?><br><?= e($order['ship_line1']) ?> <?= e($order['ship_line2']) ?><br><?= e($order['ship_city']) ?>, <?= e($order['ship_state']) ?> - <?= e($order['ship_pincode']) ?></p><?php if ($order['notes']): ?><p><strong>Notes:</strong> <?= e($order['notes']) ?></p><?php endif; ?></div></div>
<div><div class="panel"><h3>Update status</h3><form class="form" method="post" action="<?= e(url('admin/orders/' . $order['id'] . '/status')) ?>"><?= csrf_field() ?>
<label>Status <select name="status"><?php foreach ($statuses as $s): ?><option <?= $s === $order['status'] ? 'selected' : '' ?>><?= e($s) ?></option><?php endforeach; ?></select></label>
<label>Courier <input name="courier" value="<?= e($order['courier']) ?>"></label><label>Tracking number <input name="tracking_no" value="<?= e($order['tracking_no']) ?>"></label><label>Note to customer <input name="note"></label><button class="btn btn-dark">Update</button></form></div>
<div class="panel"><h3>History</h3><ul class="timeline"><?php foreach (array_reverse($timeline) as $t): ?><li><strong><?= e($t['status']) ?></strong> <span class="muted small"><?= e($t['created_at']) ?></span><?= $t['note'] ? '<br><span class="muted">' . e($t['note']) . '</span>' : '' ?></li><?php endforeach; ?></ul></div></div></div>
